// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: deposit amount and a bool to decide whether attacker will attempt reentrancy
    function testFuzz_property(uint256 amount, bool doReenter) public {
        // keep amount in a sensible wide range, and >= 1 wei
        amount = bound(amount, 1, 10 ether);

        // deploy attacker that will try to reenter Put during Put via fallback
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund attacker and this test caller so they can send ethers
        vm.deal(address(attacker), amount);

        // initial balance snapshot of attacker as seen by c
        // ensure minimum sum constraint: use either amount >= MinSum or use >0 and still test general property
        // MinSum in contract is 1 ether; keep wide: allow both cases — property still holds for any amount

        // perform deposit from attacker: attacker will optionally reenter when doReenter==true
        attacker.setReenter(doReenter);

        // make the deposit call from attacker externally
        // the attacker will call c.Put and possibly reenter during its fallback
        attacker.doPut{value: amount}();

        // After Put completes, the recorded balance for attacker (Acc[attacker].balance) must equal amount
        // because starting balance in contract for that address was zero and Put just adds msg.value
        // (the reference prevents reentrant nested Put from corrupting the accounting)
        C.Holder memory h = c.Acc(address(attacker));
        assertTrue(h.balance == amount);
    }
}

// Minimal reentrant attacker: calls c.Put in doPut; its fallback will attempt to call Put again if enabled.
contract ReentrantAttacker {
    C public c;
    bool public reenter;

    constructor(address _c) payable {
        c = C(_c);
    }

    function setReenter(bool r) public {
        reenter = r;
    }

    // external entry: call Put on c with unlockTime 0
    function doPut() public payable {
        // forward the balance already on this contract to c
        c.Put{value: msg.value}(0);
    }

    // fallback will be triggered if c makes an external call to this contract during Put
    fallback() external payable {
        if (reenter) {
            // attempt to reenter Put while still in outer Put (this will succeed only if nonReentrant_ is broken)
            // send 0 value to reenter; keep gas low-ish implicitly
            c.Put{value: 0}(0);
        }
    }
}

