pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: deposit amount and an arbitrary seed to vary attacker behavior
    function testFuzz_property(uint256 deposit, uint256 seed) public {
        // keep deposit in a reasonable range and non-zero
        deposit = bound(deposit, 1 wei, 10 ether);

        // deploy an attacker that will reenter during Put
        Attacker attacker = new Attacker(address(c), seed % 2 == 0);

        // fund attacker
        vm.deal(address(attacker), deposit * 2);

        // record prior balance in contract for attacker
        (uint priorBalance, ,) = c.Acc(address(attacker));

        // attacker will call Put{value:deposit} and may reenter to call Put again
        attacker.attack{value: deposit}();

        // observe final recorded balance via public getter
        (uint finalBalance, ,) = c.Acc(address(attacker));

        // The universal property: after Put completes, recorded balance == prior + deposit
        // On reference contract this holds for all inputs; on mutant (require removed) a reentrant nested Put can cause finalBalance > prior + deposit for some inputs
        assertTrue(finalBalance == priorBalance + deposit);
    }
}

// Minimal reentrant attacker: on fallback it will (optionally) reenter Put once
contract Attacker {
    C c;
    bool doReenter;
    constructor(address _c, bool _doReenter) payable {
        c = C(_c);
        doReenter = _doReenter;
    }

    // kick off attack: call Put on C
    function attack() external payable {
        // call Put on C; this will trigger fallback in C which calls Put(0) again if needed
        c.Put{value: msg.value}(block.timestamp + 1);
    }

    // fallback will be triggered if C sends ether back or if C calls Put via fallback semantics
    fallback() external payable {
        // if configured, attempt a reentrant Put into c to increase recorded balance during outer Put
        if (doReenter) {
            // call Put again with some small value funded from this contract
            // ensure we have some gas and balance; we only reenter once
            uint256 amt = msg.value / 2;
            if (amt > 0) {
                c.Put{value: amt}(block.timestamp + 1);
            }
            doReenter = false;
        }
    }
}

