pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz: attacker deposit amount and a chosen unlockTime candidate
    function testFuzz_property(uint256 deposit, uint256 unlockTimeCandidate) public {
        // keep deposit in a reasonable range and non-zero so MinSum interaction is possible
        deposit = bound(deposit, 1 wei, 10 ether);
        // pick an EOA actor for the depositor
        address actor = address(0xBEEF);
        vm.deal(actor, deposit);

        // Deploy a reentrant attacker that on receiving ether will call back into c.Put
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        // fund attacker so it can send value when initiating Put
        vm.deal(address(attacker), deposit);

        // The adversarial behaviour depends on unlockTimeCandidate: attacker will attempt to
        // set unlock time to either a past time or a future time during reentry. We let fuzzer choose.
        uint256 desiredUnlock = unlockTimeCandidate;

        // start the attack: attacker calls Put with desiredUnlock and value=deposit
        // Use try/catch to ensure we observe completion without test revert
        bool ok;
        try attacker.initiate{value: deposit}(desiredUnlock) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a completed Put, the invariant we assert is:
        // c.Acc(attacker).unlockTime >= block.timestamp
        // The reference implementation (with require(!locked_)) ensures during Put the stored
        // unlockTime is set to max(_unlockTime, block.timestamp) and cannot end up < block.timestamp
        // The mutant removing the require may allow reentrant nesting that causes a different final
        // stored unlockTime for some inputs; thus this universal property holds for reference
        // but is falsified by the mutant for some fuzzed inputs.

        // Read the stored holder for attacker via the public mapping getter
        (, uint256 storedBalance) = getHolder(address(attacker)); // balance read to ensure mapping exists
        // Now assert the universal property using the public unlockTime getter
        uint256 finalUnlock = getUnlockTime(address(attacker));
        assertTrue(finalUnlock >= block.timestamp);
    }

    // helpers to read the public struct mapping Acc: solidity auto-generated getter has signature
    // function Acc(address) public view returns (uint unlockTime, uint balance);
    function getHolder(address a) internal view returns (uint256, uint256) {
        try c.Acc(a) returns (uint256 u, uint256 b) {
            return (u, b);
        } catch {
            return (0,0);
        }
    }
    function getUnlockTime(address a) internal view returns (uint256) {
        try c.Acc(a) returns (uint256 u, uint256) {
            return u;
        } catch {
            return 0;
        }
    }
}

// A minimal reentrant attacker: on receiving ether it will call back into c.Put once
contract ReentrantAttacker {
    C immutable c;
    bool reentered;
    constructor(C _c) payable { c = _c; }

    // initiate starts the first Put; when fallback receives value it will reenter once
    function initiate(uint256 _unlockTime) external payable {
        // call Put on c; this will invoke our fallback during the external call if c sends us ether
        c.Put{value: msg.value}(_unlockTime);
    }

    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // attempt reentrant call setting unlock time to arbitrary value (0 here)
            // forward no value to avoid consuming more balance than available
            try c.Put{value: 0}(0) {
                // ignore
            } catch {
                // ignore
            }
        }
    }
}

