pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(address(this)); }

    // fuzzed params: deposit amount and collect amount and attacker starting balance
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, uint256 attackerBalance) public {
        // keep amounts in range and non-zero
        depositAmt = bound(depositAmt, 1 wei, 10 ether);
        collectAmt = bound(collectAmt, 1 wei, 10 ether);
        vm.assume(collectAmt <= depositAmt);

        // deploy attacker that will try to re-enter on receive
        attacker = new Attacker(address(c));

        // fund attacker externally so it can deposit
        vm.deal(address(attacker), attackerBalance + depositAmt + 1 ether);

        // attacker deposits depositAmt into c via Put (calls through attacker so it is the msg.sender)
        // Attacker contract will perform the Put using its own address
        attacker.doPut{value: depositAmt}(depositAmt);

        // Now attempt to Collect from attacker account: have attacker call Collect to receive funds.
        // collectAmt must be <= stored balance and >= MinSum (MinSum = 1 ether in contract)
        // Ensure collectAmt and depositAmt obey MinSum constraint for possibility of success
        vm.assume(depositAmt >= 1 ether);
        vm.assume(collectAmt >= 1 ether);

        // record balance before collect
        uint before = c.Acc(address(attacker)).balance;

        // Trigger collect via attacker which will attempt to re-enter during its fallback
        bool ok;
        try attacker.doCollect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After the operation completes, reference implementation guarantees that
        // the stored balance equals previous balance minus any successful transfer amount.
        // In particular, if the external call (to attacker) returned success then stored balance == before - collectAmt.
        // We assert that either the Collect failed (ok == false) or the stored balance decreased by exactly collectAmt.
        // This is a general invariant satisfied by the correct contract; the mutant allowing reentrancy can violate it.
        uint after = c.Acc(address(attacker)).balance;

        // single assertion capturing the universal property: if the external call succeeded then balance decreased exactly by collectAmt
        // (reads c through its public getter Acc)
        assertTrue(!ok || after + collectAmt == before);
    }
}

