        // Single assertion: after the forwarded Put, the balance recorded for the forwarder
        // must have increased exactly by the forwarded amount (works for all inputs on ref C).
        uint256 after = c.Acc(address(f)).balance();
        assertTrue(after == before + amount);
    }
}

// Minimal forwarding contract: receives ETH and calls C.Put preserving msg.sender = forwarder
contract Forwarder {
    C immutable c;
    constructor(address _c) {
        c = C(_c);
    }

    // Allow receiving ETH and then call Put on C
    function callPut(uint256 _unlockTime) external payable {
        // forward the ETH to c, so c sees msg.sender == address(this) and tx.origin == original caller
        c.Put{value: msg.value}(_unlockTime);
    }

    // allow direct receive
    receive() external payable {}
}

