contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    // fuzzed params: payer (an EOA) and amount to send, and a boolean whether the intermediary contract is used
    function testFuzz_property(address payer, uint256 amount, bool useIntermediate) public {
        // keep payer non-zero and amount within a reasonable bound but wide
        vm.assume(payer != address(0));
        amount = bound(amount, 1, 5 ether);

        // Deploy an intermediary contract that will act as msg.sender when calling c.Put
        Intermediary impl = new Intermediary(c);

        // Ensure the payer (an EOA) has funds
        vm.deal(payer, amount + 1 ether);

        // If useIntermediate is true, payer sends ETH to the intermediary which then calls c.Put,
        // making msg.sender == address(impl) and tx.origin == payer. This distinguishes reference vs mutant.
        if (useIntermediate) {
            // fund intermediary and have it call C.Put on behalf of payer by using a tx from payer
            vm.prank(payer);
            // call intermediary with value; it will forward the call to c.Put and become msg.sender
            impl.buy{value: amount}();

            // After call, the invariant for the correct contract: Acc[intermediary].balance increased by amount
            // We assert that reading the public getter returns the expected balance (amount)
            // Use the public mapping getter: Acc(address).balance is accessible as Acc(address).
            // c.Acc(impl) returns the Holder struct; accessing .balance is done by the autogenerated getter
            // which in Solidity returns the tuple; but public mapping of struct returns individual fields by name
            // so we read the balance via c.Acc(address(impl)).balance()
            // However Solidity autogenerated getter for mapping to struct provides a function Acc(address) returning (uint unlockTime, uint balance)
            (uint256 unlockTime, uint256 bal) = c.Acc(address(impl));
            // General invariant: for the reference implementation, bal == amount. Mutant that uses tx.origin writes to Acc[payer] instead,
            // so Acc[impl].balance may remain 0 for some inputs, causing this assertion to fail.
            assertTrue(bal == amount);
        } else {
            // If not using intermediary, payer calls c.Put directly; then msg.sender == tx.origin == payer,
            // both reference and mutant behave the same for this case. We still assert the property for the direct call.
            vm.prank(payer);
            c.Put{value: amount}(0);
            (uint256 ut, uint256 bal2) = c.Acc(payer);
            assertTrue(bal2 == amount);
        }
    }
}

