contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function performing the test
    // params:
    // depositor - address that will hold funds in c (must be this contract when calling)
    // depositAmt - amount to deposit into c for the holder
    // collectAmt - amount to attempt to collect
    // unlockTime - unlock time to set (>= block.timestamp)
    function check(address depositor, uint depositAmt, uint collectAmt, uint unlockTime) public {
        // preconditions: this contract must be the depositor so it can call Collect as msg.sender
        require(depositor == address(this));
        // ensure we have enough ETH to deposit
        require(address(this).balance >= depositAmt);
        // deposit into c: Put with given unlockTime
        c.Put{value: depositAmt}(unlockTime);

        // read recorded balance after deposit
        uint balBefore = c.Acc(address(this)).balance;

        // ensure deposit recorded properly
        require(balBefore >= depositAmt);
        // require minSum condition so Collect may proceed: ensure balBefore >= c.MinSum() and >= collectAmt
        require(balBefore >= c.MinSum());
        require(balBefore >= collectAmt);
        // ensure unlock time has passed by requiring unlockTime < block.timestamp (or equal handled as > in contract)
        // The original contract sets acc.unlockTime = max(_unlockTime, block.timestamp) in Put,
        // so if we passed unlockTime <= block.timestamp then stored unlockTime == block.timestamp and Collect needs block.timestamp>acc.unlockTime.
        // To satisfy that, demand unlockTime == 0 so fallback behavior used or set earlier and rely on caller supplying an unlockTime < block.timestamp.
        // Simpler: require that block.timestamp > c.Acc(address(this)).unlockTime so Collect's time check passes
        require(block.timestamp > c.Acc(address(this)).unlockTime);

        // attempt to collect; this may revert if transfer semantics differ in mutant
        // The call's success or revert is captured by whether execution continues past this line.
        c.Collect(collectAmt);

        // read recorded balance after Collect
        uint balAfter = c.Acc(address(this)).balance;

        // Rule: stored balance decreased exactly by collectAmt when Collect returned (succeeded);
        // if Collect had reverted the state, execution would not reach here. Therefore here we assert the balance decreased by collectAmt.
        assert(balBefore == balAfter + collectAmt);
    }

    // allow this contract to receive ETH for setup
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: amount to attempt to collect
    function run(uint _am) public payable {
        // Precondition: ensure this test account has sufficient recorded balance and unlock time passed
        // We cannot directly set Acc in c, but we can rely on calling c.Put by sending Ether to increase balance.
        // Require we have enough ETH here to deposit and then attempt Collect for same value.
        require(address(this).balance >= _am, "insufficient test balance");
        // First deposit _am to ensure recorded balance >= _am and also >= MinSum if _am >= MinSum.
        // To satisfy MinSum we require _am >= c.MinSum(). Call MinSum via public getter.
        uint min = c.MinSum();
        require(_am >= min, "_am must be at least MinSum to satisfy withdrawal precondition");

        // Deposit funds and set unlockTime in fallback/Put: call Put with unlockTime = 0 so fallback uses block.timestamp -> unlockTime = now
        c.Put{value: _am}(0);

        // Now try to Collect the same amount; on the original contract this should not revert when preconditions hold
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: when caller has deposited at least MinSum and at least _am and unlockTime has passed (we used Put with 0 so unlockTime == block.timestamp), Collect should succeed (not revert).
        // We expressed the necessary condition by ensuring _am >= MinSum and depositing _am just before calling Collect.
        assert(reverted == false);
    }

    receive() external payable { }
}

