        // So call Collect and observe whether it reverts.
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }

        // Rule: If we deposited at least MinSum and deposited at least _am, then Collect should not revert (original uses low-level call that forwards gas and returns false on failure but does not revert the whole tx). This invariant holds for the original but is violated by the mutant which uses transfer and may revert.
        uint minSum = c.MinSum();
