    // Parameters:
    //   uint depositAmount - amount to deposit into c for this test (must be >= minSum and >= withdrawAmount)
    //   uint withdrawAmount - amount to attempt to withdraw via Collect
    //   uint unlockTime - a timestamp <= block.timestamp to allow withdrawal
    function run(uint depositAmount, uint withdrawAmount, uint unlockTime) public payable {
        // Precondition: this contract must have enough balance to deposit into c
        require(address(this).balance >= depositAmount, "insufficient test balance");
        // Ensure deposit will be large enough to satisfy MinSum and the requested withdrawal
        require(depositAmount >= withdrawAmount, "deposit < withdraw");

        // Make a deposit into c on behalf of this test contract
        // Note: C.Put is payable and will record Acc[address(this)].balance
        c.Put{value: depositAmount}(unlockTime);

        // Try to collect withdrawAmount; record whether it reverted
        bool reverted;
        try c.Collect(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: if depositAmount >= withdrawAmount and depositAmount >= c.MinSum() and unlockTime <= block.timestamp
        // then Collect must NOT revert when called by this contract (an EOA-like caller of c). We observe revert flag.
        // We can call c.MinSum() (public) to compare.
        uint minSum = c.MinSum();
        bool precondsHold = (depositAmount >= withdrawAmount) && (depositAmount >= minSum) && (unlockTime <= block.timestamp);
        assert(!precondsHold || !reverted);
    }

